beforeExample:
public class StringComparison {
    public void check(String s) {
        boolean isReallyEmpty = s.equals("");
        if (!s.equals("")) {
            System.out.println("Not empty.");
        }
        String someText = s.trim();
        if (someText != null && !someText.equals("")) {
            System.out.println("Trimmed not empty.");
        }
    }
    public void testNull() {
        String s = null;
        try {
            s.equals(""); // Will throw NullPointerException
        } catch (NullPointerException e) {
            System.out.println("NPE as expected");
        }
    }
}

afterExample:
public class StringComparison {
    public void check(String s) {
        boolean isReallyEmpty = s.isEmpty();
        if (!s.isEmpty()) {
            System.out.println("Not empty.");
        }
        String someText = s.trim();
        if (someText != null && !someText.isEmpty()) {
            System.out.println("Trimmed not empty.");
        }
    }
    public void testNull() {
        String s = null;
        try {
            s.isEmpty(); // Will throw NullPointerException
        } catch (NullPointerException e) {
            System.out.println("NPE as expected");
        }
    }
}

